 \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [189, 1321, 1303, 1418], \"page_id\": 11}], \"content\": \"I shall be glad to receive and to give careful consideration to suggestions for improving the Bulletin so as to make it serve its purpose more adequately.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 1473, 1313, 1535], \"page_id\": 11}], \"content\": \"Henry Morgenthau, Jr. Secretary of the Treasury.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [724, 1951, 787, 1974], \"page_id\": 11}], \"content\": \"-1-\", \"description\": null, \"id\": 7, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [154, 409, 1352, 1611], \"page_id\": 12}], \"content\": \"\", \"description\": null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [331, 984, 1168, 1020], \"page_id\": 13}], \"content\": \"RECEIPTS AND EXPENDITURES\", \"description\": null, \"id\": 0, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [715, 1218, 782, 1245], \"page_id\": 13}], \"content\": \"-2-\", \"description\": null, \"id\": 1, \"type\": \"page_footer\"}, {\"bbox\": [{\"coord\": [282, 121, 503, 153], \"page_id\": 15}], \"content\": \"Summary Tables\", \"description\": null, \"id\": 0, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [259, 159, 505, 196], \"page_id\": 15}], \"content\": \"(In millions of dollars)\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [261, 196, 496, 228], \"page_id\": 15}], \"content\": \"RECEIPTS AND EXPENDITURES\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [86, 235, 694, 421], \"page_id\": 15}], \"content\": \"<table><tr><th rowspan=\\\"2\\\"></th><th colspan=\\\"6\\\">First 6 months fiscal year</th><th rowspan=\\\"2\\\">Change '38 -'39</th></tr><tr><th>1934</th><th>1935</th><th>1936</th><th>1937</th><th>1938</th><th>1939</th></tr><tr><td>Receipts.....</td><td>1,469</td><td>1,845</td>